/**
 * Issue #2456 (owner ruling C2) — BYTE-IDENTITY guard for the shared marker
 * shell after the additive `interactive?: boolean` option.
 *
 * The inline snapshots below were GENERATED BY RUNNING THIS FILE AGAINST THE
 * PRE-CHANGE SOURCE (`markerPrimitives.ts` + `AreaMarkerLayer.tsx` at the PR
 * base `ad7dbca2`, with the new option absent), then the post-change source
 * was restored and the file re-run unchanged. A passing run therefore proves
 * every existing caller's output is byte-for-byte what it was before this PR
 * when the option is omitted — not merely "an optional param was added".
 *
 * The final describe block pins the ONLY permitted difference for
 * `interactive: false`: the outer shell's style (`pointer-events:none`,
 * `cursor:default`), and proves the AREA_SET draft-member card
 * (AreaSetCandidateCalloutLayer) is that same shell with the interactive
 * attrs removed and no numeric count.
 */

import { describe, it, expect, vi } from 'vitest';

