describe('`interactive: false` — the ONLY permitted differences', () => {
  it('markerShellHtml: identical except the outer shell style', () => {
    const on = markerShellHtml({ ...BASE_OPTS, actionKind: 'view-homes', journey: 'areas', isSelected: true });
    const off = markerShellHtml({
      ...BASE_OPTS,
      actionKind: 'view-homes',
      journey: 'areas',
      isSelected: true,
      interactive: false,
    });
    expect(on).toContain(`style="${MARKER_SHELL_STYLE}"`);
    expect(off).toContain('pointer-events:none;cursor:default;');
    expect(off).not.toContain('pointer-events:auto');
    expect(off).not.toContain('cursor:pointer');
    expect(
      off.replace(
        'transform:translate(-50%,-100%);font-family:inherit;pointer-events:none;cursor:default;outline:none;',
        MARKER_SHELL_STYLE,
      ),
    ).toBe(on);
  });

  it('the draft-member card (AreaSetCandidateCalloutLayer) is this same shell — identical to the selected leaf shell except the permitted deltas, and carries NO digits', () => {
    const memberHtml = iconHtml(
      makeAreaSetDraftMemberIcon({ areaKey: 'a:IN|KA|Bengaluru|Hebbal', label: 'Hebbal', lat: 13.05, lon: 77.59 }),
    );
    expect(memberHtml).not.toMatch(/tabindex=/);
    expect(memberHtml).not.toMatch(/role="button"/);
    expect(memberHtml).not.toMatch(/aria-label=/);
    expect(memberHtml).toContain('aria-hidden="true"');
    expect(memberHtml).toContain('data-interactive="false"');
    expect(memberHtml).toContain('pointer-events:none;cursor:default;');
    // Owner ruling (count truthfulness): no numeric hero count anywhere on the card.
    const bodyText = memberHtml.match(/<div class="rc-body"[^>]*>([\s\S]*?)<\/div><div class="rc-footer"/)?.[1] ?? '';
    expect(bodyText.replace(/<[^>]+>/g, '')).not.toMatch(/\d/);
    expect(bodyText).toContain(DRAFT_MEMBER_SECONDARY_TEXT);
    // Same shell as the interactive selected leaf: swap the two permitted
    // deltas back and the shell/footer/tail markup is byte-identical to
    // markerShellHtml's own output for the same identity content.
    const identityHtml = memberHtml.match(/<div class="rc-body"[^>]*>([\s\S]*?)<\/div><div class="rc-footer"/)?.[1] ?? '';
    const reference = markerShellHtml({
      shellAttrs: markerInteractiveAttrs({ testId: 'x', nodeKey: 'k', selected: true, ariaLabel: 'l' }),
      titleAttr: '',
      actionKind: 'view-homes',
      journey: 'areas',
      widthPx: 172,
      isSelected: true,
      journeyAttr: '',
      fontSansAttr: escapeHtml(FONT_SANS),
      identityHtml,
      footerIconHtml: homeGlyphSvg(PAPER),
      footerLabelText: 'View homes',
    });
    const normalised = memberHtml
      .replace(
        /<div data-testid="area-set-draft-member-marker" data-node-key="[^"]*" data-selected="true" data-interactive="false" aria-hidden="true"/,
        `<div ${markerInteractiveAttrs({ testId: 'x', nodeKey: 'k', selected: true, ariaLabel: 'l' })}`,
      )
      .replace(
        'transform:translate(-50%,-100%);font-family:inherit;pointer-events:none;cursor:default;outline:none;',
        MARKER_SHELL_STYLE,
      );
    expect(normalised).toBe(reference);
  });
});
